/// <summary>
/// Extension of formDataSource PurchAgreementHeader in form PurchAgreement
/// </summary>
[ExtensionOf(formDataSourceStr(PurchAgreement, PurchAgreementHeader))]
final class AVAPurchAgreement_PurchAgreementHeaderDS_Extension
{
}

Method.Source:
/// <summary>
/// extended validateWrite method
/// </summary>
/// <returns>boolean</returns>
public boolean validateWrite()
{
    PurchAgreementHeader    avaPurchAgreementHeader = this.formRun().dataSource('PurchAgreementHeader').cursor();
    boolean                 orderConfirmationUpdateLoc  = avaPurchAgreementHeader.AVAOrderConfirmation != avaPurchAgreementHeader.orig().AVAOrderConfirmation;
    boolean                 effectivePriceLoc           = avaPurchAgreementHeader.AVAEffectivePrice != avaPurchAgreementHeader.orig().AVAEffectivePrice;

    boolean ret = next validateWrite();

    if(ret)
    {
        if(orderConfirmationUpdateLoc
            && this.avaTable2LineUpdate(fieldNum(PurchTable, AVAOrderConfirmation), fieldId2PName(tableNum(PurchAgreementHeader), fieldNum(PurchAgreementHeader, AVAOrderConfirmation))))
        {
            avaPurchAgreementHeader.avaUpdateAgreementLineOrderConfirmation();
        }

        if(effectivePriceLoc
            && this.avaTable2LineUpdate(fieldNum(PurchTable, AVAEffectivePrice), fieldId2PName(tableNum(PurchAgreementHeader), fieldNum(PurchAgreementHeader, AVAOrderConfirmation))))
        {
            avaPurchAgreementHeader.avaUpdateAgreementLineOrderConfirmation();
        }
    }

    return ret;
}

/// <summary>
/// creates a Dialog for updated field if parameter enabled and returns results
/// </summary>
/// <param name = "_paramFieldId">parameter fieldId</param>
/// <param name = "_updatedfieldPName">PName of table field to be updated</param>
/// <returns>boolean</returns>
public boolean avaTable2LineUpdate(FieldId _paramFieldId, str _updatedfieldPName)
{
    TradeTable2LineUpdate avaTable2LineUpdate = PurchTable2LineParameters::find(_paramFieldId).Table2LineUpdate;

    if((avaTable2LineUpdate == TradeTable2LineUpdate::Prompt
            && this.avaUpdateLineDialog(_updatedfieldPName) == DialogButton::Yes)
            || avaTable2LineUpdate == TradeTable2LineUpdate::Always)
    {
        return true;
    }

    return false;    
}

/// <summary>
/// Creates a Dialog and returns result for modified FieldId
/// </summary>
/// <param name = "_fieldPName">PName of table field to be updated</param>
/// <returns>DialogButton</returns>
public DialogButton avaUpdateLineDialog(str _fieldPName)
{
    str strMessage = strFmt(SysLabel::labelId2String2("@NDX:NXAOrderConfirmationDialog"), _fieldPName);

    return Box::yesNo(strMessage,DialogButton::No);
}
